import * as T from './vendor/three.module.min.js';
const geometry=new T.IcosahedronGeometry(1,1),stamp=new T.Object3D(),axis=new T.Vector3(0,0,1),direction=new T.Vector3(),color=new T.Color();
export function makeFlameEffect(parent){const group=new T.Group(),material=new T.MeshBasicMaterial({transparent:true,opacity:.6,depthWrite:false,blending:T.AdditiveBlending,vertexColors:false}),particles=new T.InstancedMesh(geometry,material,36);particles.frustumCulled=false;group.add(particles);parent.add(group);group.visible=false;return{group,update(start,end,t,active){group.visible=active;if(!active)return;direction.copy(end).sub(start);const length=direction.length();group.position.copy(start);group.quaternion.setFromUnitVectors(axis,direction.normalize());for(let i=0;i<36;i++){const f=(t*2.8+i/36)%1,angle=i*2.399+t*.8,radius=f*length*.2;stamp.position.set(Math.sin(angle)*radius*(i%3)/3,Math.cos(angle)*radius*(i%4)/4,f*length);stamp.rotation.set(t*4+i,i,t*2);const size=(.08+f*length*.09)*Math.min(1,(1-f)*5);stamp.scale.set(size,size,size*1.65);stamp.updateMatrix();particles.setMatrixAt(i,stamp.matrix);color.set(f<.18?'#fff3b2':f<.55?'#ffb239':'#ee4e21');particles.setColorAt(i,color);}particles.instanceMatrix.needsUpdate=true;particles.instanceColor.needsUpdate=true;},dispose(){particles.dispose();material.dispose();group.removeFromParent();}};}
